#include <stdio.h>

int square(int x) { return x * x; }

int main() {
    int sum = 0;
    for (int i = 1; i <= 10; i++) {
        sum += square(i);
    }
    printf("sum of squares 1..10 = %d\n", sum);
    return 0;
}

